import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** Where a claim is in its life: DRAFT -> OPEN -> SETTLED; DRAFT or OPEN -> VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/**
 * A claim as the store holds it: the amount with two decimals, the date as yyyy-MM-dd; its number
 * is the sheet's next one when it was opened, null while a draft (a voided claim keeps it); its due is the
 * one fixed when it was settled (two decimals), null while it is live; openedBy is the user who
 * opened it, null while a draft; stated is whether its person's last statement bound it to a figure,
 * statedDue that figure (two decimals; null: n/a) — it then shows and totals that, not its live figure;
 * corrects is, for a correction (a negative amount), the number of the settled claim it corrects, null otherwise.
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: number | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: number | null;
};

/**
 * Whether a claim counts toward claimed, due-total and every live total: only OPEN and SETTLED do, and
 * an OPEN one not while its person is held.
 */
export const counts = (c: Claim, held = false) => c.status === 'SETTLED' || (c.status === 'OPEN' && !held);

/** The ids of the people on hold, whose open claims count in no live total. */
export const heldIds = (people: { id: number; held: boolean }[]) => new Set(people.filter((p) => p.held).map((p) => p.id));

/** The fields the claim form submits; a blank date is the sheet's today; corrects names, by number, the claim a correction corrects. */
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d+(\.\d{1,2})?|\.\d{1,2})$/;

/** An amount the claim form takes: negative for a correction, with at most two decimals. */
export const SIGNED_AMOUNT = /^-?(\d+(\.\d{1,2})?|\.\d{1,2})$/;

/** The query key for the sheet's claims; under sheetKey, so re-loading the sheet re-reads them. */
export const claimsKey = (sheet: string) => [...sheetKey(sheet), 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: !!sheet,
  });
}

/** The sum of the counted claims' amounts, with two decimals; added in cents so it is exact. `held` holds the people on hold. */
export function claimed(claims: Claim[], held: Set<number>): string {
  const cents = claims.filter((c) => counts(c, held.has(c.personId))).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import type { Person } from '../people/people';
import { SIGNED_AMOUNT, claimsKey, useClaims } from './claims';
import type { Claim, ClaimInput } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';

const EMPTY: ClaimInput = { amount: '', date: '', note: '', corrects: '' };

// A person's claims, newest first, and the form that adds one — or, while a claim's editor is
// open, saves that claim's changes. Opening an editor fills the form with the claim's values.
export function PersonClaims({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  const [form, setForm] = useState<ClaimInput>(EMPTY);
  const [editing, setEditing] = useState<number | undefined>(undefined);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const close = () => {
    setEditing(undefined);
    setForm(EMPTY);
    setError('');
  };

  const save = useMutation({
    mutationFn: (input: ClaimInput) =>
      editing === undefined
        ? postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/claims?user=${encodeURIComponent(user)}`, input)
        : putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${editing}?user=${encodeURIComponent(user)}`, input),
    onSuccess: async () => {
      close();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () => setError('That claim could not be saved.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!SIGNED_AMOUNT.test(form.amount.trim())) {
      setError('Type an amount with at most two decimals.');
      return;
    }
    const date = form.date.trim();
    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    once(() => save.mutateAsync(form));
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const edit = (c: Claim) => {
    setEditing(c.id);
    setForm({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects === null ? '' : String(c.corrects) });
    setError('');
  };

  return (
    <td data-testid="person-claims">
      <ul>
        {claims.map((c) => (
          <li key={c.id} data-testid={`claim-row-${c.id}`}>
            <span data-testid="claim-amount">{c.amount}</span> <span data-testid="claim-date">{c.date}</span>{' '}
            <span data-testid="claim-note" style={{ whiteSpace: 'pre' }}>
              {c.note}
            </span>{' '}
            <ClaimRowValues.Slot claim={c} person={person} />{' '}
            {editing === c.id ? (
              <button type="button" data-testid="claim-cancel" onClick={close}>
                Cancel
              </button>
            ) : (
              <button type="button" data-testid="claim-edit" onClick={() => edit(c)}>
                Edit
              </button>
            )}
          </li>
        ))}
      </ul>
      <form onSubmit={submit} data-testid="claim-form">
        <input
          data-testid="claim-form-amount"
          placeholder="Amount"
          value={form.amount}
          onChange={(e) => change({ amount: e.target.value })}
        />
        <input
          data-testid="claim-form-date"
          placeholder="yyyy-mm-dd"
          value={form.date}
          onChange={(e) => change({ date: e.target.value })}
        />
        <input
          data-testid="claim-form-note"
          placeholder="Note"
          value={form.note}
          onChange={(e) => change({ note: e.target.value })}
        />
        <input
          data-testid="claim-form-corrects"
          placeholder="Corrects claim no."
          value={form.corrects}
          onChange={(e) => change({ corrects: e.target.value })}
        />
        <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
          {editing === undefined ? 'Add claim' : 'Save claim'}
        </button>
        {error && <span data-testid="claim-form-error">{error}</span>}
      </form>
    </td>
  );
}
